SELECT a.id, a.project_id AS projectId, a.title, a.description, a.version, a.category, '' AS equipmentInfo, a.is_submitted AS isSubmitted, a.is_deleted AS isDeleted, a.is_public AS isPublic, a.approved, a.submitted_by AS submittedBy, a.approved_by AS approvedBy, a.submitted_at AS submittedAt, a.approved_at AS approvedAt, a.submitted_by_name AS submittedByName, '' AS projectTitle FROM archives a WHERE a.is_deleted = FALSE AND a.approved = TRUE AND a.is_submitted = TRUE
AND (a.title LIKE CONCAT('%', #{search}, '%') OR a.description LIKE CONCAT('%', #{search}, '%') OR a.submitted_by_name LIKE CONCAT('%', #{search}, '%'))
AND a.category = #{category}
AND YEAR(a.submitted_at) = #{year}
ORDER BY a.approved_at DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM archives a WHERE a.is_deleted = FALSE AND a.approved = TRUE AND a.is_submitted = TRUE
AND (a.title LIKE CONCAT('%', #{search}, '%') OR a.description LIKE CONCAT('%', #{search}, '%') OR a.submitted_by_name LIKE CONCAT('%', #{search}, '%'))
AND a.category = #{category}
AND YEAR(a.submitted_at) = #{year}

